function isAuthError(value){const msg=String(value?.message||value?.details||value?.error||value||'');return Number(value?.status)===401||/jwt|session.*expired|expired.*session|not authenticated|authentication required|invalid.*token|token.*expired|unauthorized/i.test(msg);}
function handleAuthLoss(message='Your secure session expired. Sign in again to resume cloud sync. Offline changes remain on this device.'){session=null;me=null;clearTimeout(syncTimer);clearInterval(pollTimer);pollTimer=null;activeConversation=null;runtime?.toast?.(message);}
async function rpc(name,args={}){
  const spec=RPC_SPECS[name];if(!spec)throw new Error(`Unsupported RPC mapping: ${name}`);
  const {data,error}=await neon.rpc('app_api',{p_action:spec[0],p_payload:spec[1](args)});
  if(error){const e=new Error(error.message||error.details||'Cloud request failed');e.status=isAuthError(error)?401:/rate_limit/i.test(e.message)?429:/permission|not_a_|required|allowed/i.test(e.message)?403:400;e.data=error;if(e.status===401)handleAuthLoss();throw e;}
  if(data&&typeof data==='object'&&!Array.isArray(data)&&data.error){const e=new Error(data.error);e.status=Number(data.status||400);e.data=data;if(e.status===401||isAuthError(data))handleAuthLoss();throw e;}
  return data;
}
function requestBody(options={}){if(!options.body)return {};if(typeof options.body==='string'){try{return JSON.parse(options.body)}catch{return {}}}return options.body||{};}
async function api(url,options={}){
  const u=new URL(url,location.origin),path=u.pathname,method=(options.method||'GET').toUpperCase(),b=requestBody(options);let m;
  if(path==='/api/me')return rpc('app_me');
  if(path==='/api/teams'&&method==='POST')return rpc('app_team_create',{p_payload:b});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/state$/)))return method==='PUT'?rpc('app_team_update',{p_team:m[1],p_revision:Number(b.revision||0),p_team_record:b.teamRecord||{},p_context:b.context||{}}):rpc('app_team_state',{p_team:m[1]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/members$/)))return rpc('app_team_members',{p_team:m[1]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/invitations$/)))return method==='POST'?rpc('app_invitation_create',{p_team:m[1],p_email:b.email,p_role:b.role||'guardian',p_athlete_client_key:b.athleteClientKey||null,p_expires_hours:Number(b.expiresHours||72)}):rpc('app_invitation_list',{p_team:m[1]});
  if(path==='/api/invitations/accept')return rpc('app_invitation_accept',{p_token:b.token});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/join-codes$/)))return rpc('app_join_create',{p_team:m[1],p_role:b.role||'guardian',p_athlete_client_key:b.athleteClientKey||null,p_max_uses:Number(b.maxUses||1),p_expires_hours:b.expiresHours?Number(b.expiresHours):null});
  if(path==='/api/join-codes/redeem')return rpc('app_join_redeem',{p_code:b.code});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/documents$/)))return rpc('app_document_list',{p_team:m[1]});
  if((m=path.match(/^\/api\/documents\/([^/]+)\/acknowledge$/)))return rpc('app_document_ack',{p_document:m[1]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/documents\/([^/]+)$/))&&method==='DELETE')return rpc('app_document_delete',{p_team:m[1],p_document:m[2]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/events\/([^/]+)\/availability$/))){const eventId=decodeURIComponent(m[2]);return method==='PUT'?rpc('app_availability_set',{p_team:m[1],p_event_id:eventId,p_athlete_client_key:b.athleteClientKey,p_status:b.status,p_note:b.note||null}):rpc('app_availability_get',{p_team:m[1],p_event_id:eventId});}
  if(path==='/api/crypto-key'&&method==='PUT')return rpc('app_crypto_put',{p_public_key_jwk:b.publicKeyJwk||{},p_algorithm:b.algorithm||'ECDH-P256',p_version:Number(b.version||1)});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/conversations$/)))return rpc('app_conversation_create',{p_team:m[1],p_kind:b.kind,p_name:b.name||null,p_member_user_ids:b.memberUserIds||[],p_visibility:b.visibility||'team'});
  if(path==='/api/conversations')return rpc('app_conversation_list',{p_team:u.searchParams.get('teamId')||null});
  if((m=path.match(/^\/api\/conversations\/([^/]+)\/members$/)))return rpc('app_conversation_members',{p_conversation:m[1]});
  if((m=path.match(/^\/api\/conversations\/([^/]+)\/key-envelopes$/)))return rpc('app_conversation_envelopes_put',{p_conversation:m[1],p_key_version:Number(b.keyVersion||1),p_envelopes:b.p_envelopes||b.envelopes||[]});
  if((m=path.match(/^\/api\/conversations\/([^/]+)\/key-envelope$/)))return rpc('app_conversation_envelope_get',{p_conversation:m[1],p_key_version:u.searchParams.get('version')?Number(u.searchParams.get('version')):null});
  if((m=path.match(/^\/api\/conversations\/([^/]+)\/messages$/))){return method==='POST'?rpc('app_message_send',{p_conversation:m[1],p_ciphertext:b.ciphertext,p_nonce:b.nonce,p_crypto_version:b.cryptoVersion,p_client_message_id:b.clientMessageId}):rpc('app_message_list',{p_conversation:m[1],p_after:u.searchParams.get('after')||null,p_after_id:u.searchParams.get('afterId')||null});}
  if((m=path.match(/^\/api\/conversations\/([^/]+)\/read$/)))return rpc('app_message_read',{p_conversation:m[1]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/forms$/)))return method==='POST'?rpc('app_form_create',{p_team:m[1],p_title:b.title,p_description:b.description||null,p_visibility:b.visibility||'guardians',p_requires_signature:Boolean(b.requiresSignature),p_fields:b.fields||[]}):rpc('app_form_list',{p_team:m[1]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/forms\/([^/]+)\/assign$/)))return rpc('app_form_assign',{p_team:m[1],p_form:m[2],p_user:b.userId,p_athlete_client_key:b.athleteClientKey||null,p_due_at:b.dueAt||null});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/forms\/([^/]+)\/assignments$/)))return rpc('app_form_assignments',{p_team:m[1],p_form:m[2]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/forms\/([^/]+)\/submit$/)))return rpc('app_form_submit',{p_team:m[1],p_form:m[2],p_assignment:b.assignmentId||null,p_answers:b.answers||{},p_signature:b.signature||null});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/forms\/([^/]+)\/submissions$/)))return rpc('app_form_submissions',{p_team:m[1],p_form:m[2]});
  if((m=path.match(/^\/api\/teams\/([^/]+)\/notification-preferences$/)))return method==='PUT'?rpc('app_prefs_set',{p_team:m[1],p_messages:Boolean(b.messages),p_schedule:Boolean(b.schedule),p_weather:Boolean(b.weather),p_documents:Boolean(b.documents),p_forms:Boolean(b.forms)}):rpc('app_prefs_get',{p_team:m[1]});
  if(path==='/api/push/public-key')return {enabled:false,mode:'in-app'};
  throw new Error(`Unsupported cloud route: ${method} ${path}`);
}

function overlay(html){closeOverlay();const el=document.createElement('div');el.className='cloud-overlay';el.id='cloudOverlay';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-label','Team APP account panel');el.innerHTML=`<div class="cloud-sheet">${html}</div>`;document.body.appendChild(el);el.addEventListener('click',e=>{if(e.target===el)closeOverlay();});return el;}
function closeOverlay(){document.getElementById('cloudOverlay')?.remove();if(pollTimer){clearInterval(pollTimer);pollTimer=null;}activeConversation=null;}
function buttonBusy(btn,busy,label='Working…'){if(!btn)return;btn.disabled=busy;if(busy){btn.dataset.oldText=btn.textContent;btn.textContent=label;}else if(btn.dataset.oldText){btn.textContent=btn.dataset.oldText;delete btn.dataset.oldText;}}
function roleFor(remoteId){return me?.teams?.find(t=>t.id===remoteId)?.role||null;}
function activePayload(){return runtime?.getActiveCloudPayload?.()||null;}
function activeRemoteId(){return activePayload()?.teamRecord?.remoteId||null;}
async function allQueuedRows(){try{return await window.TEAM_APP_CLOUD_QUEUE?.entries?.()||[];}catch{return [];}}
async function queuedRows(){const rows=await allQueuedRows(),ownerId=me?.user?.id||session?.user?.id||null;if(!ownerId)return rows.filter(([,p])=>!p?.ownerUserId);return rows.filter(([,p])=>!p?.ownerUserId||p.ownerUserId===ownerId);}
const syncResult=(status,extra={})=>({status,...extra});
function syncResultMessage(result){
  if(result?.status==='synced'||result?.status==='created')return 'Sync complete.';
  if(result?.status==='queued')return 'Cloud is unavailable right now. Your coaching changes are saved on this device and queued to sync.';
  if(result?.status==='conflict')return 'Sync conflict detected. This team changed on another device. Choose which copy to keep.';
  if(result?.status==='queue-failed')return 'Your coaching changes remain saved locally, but they could not be added to the cloud sync queue. Reconnect before clearing site data or changing devices.';
  if(result?.status==='auth-lost')return 'Your secure session expired. Sign in again before syncing.';
  return 'Nothing new to sync.';
}

async function ensureCryptoIdentity(){if(!window.TEAM_APP_E2EE)return;const jwk=await window.TEAM_APP_E2EE.publicJwk();await api('/api/crypto-key',{method:'PUT',body:JSON.stringify({publicKeyJwk:jwk,algorithm:'ECDH-P256',version:1})});}

async function start(rt){runtime=rt;if(location.search.includes('demo=1')){hydrating=false;return;}try{const r=await authClient.getSession();session=r?.data||r;if(!session?.user){showLogin();hydrating=false;return;}await afterLogin();}catch(err){console.error('[cloud start]',err);showLogin(err.message);hydrating=false;}}
async function afterLogin(){
  session=(await authClient.getSession())?.data||session;
  const pendingInvite=new URLSearchParams(location.search).get('invite');
  if(pendingInvite){try{await api('/api/invitations/accept',{method:'POST',body:JSON.stringify({token:pendingInvite})});const u=new URL(location.href);u.searchParams.delete('invite');history.replaceState(null,'',u.pathname+u.search+u.hash);}catch(e){console.warn('[invite accept]',e);}}
  me=await api('/api/me');await ensureCryptoIdentity().catch(e=>console.warn('[e2ee identity]',e));
  if(!me.teams?.length){showFirstTeam();hydrating=false;return;}
  const queued=new Map(await queuedRows()),cloudTeams=[];
  for(const t of me.teams){try{const detail=await api(`/api/teams/${t.id}/state`);revisions.set(t.id,Number(detail.revision||0));cloudTeams.push(detail);}catch(e){console.error('[cloud team]',t.id,e);}}
  if(queued.size){for(const detail of cloudTeams)if(!queued.has(detail.id))runtime?.replaceOneCloudTeam?.(detail);}else runtime?.replaceCloudTeams?.(cloudTeams);
  hydrating=false;await flushQueue();runtime?.refresh?.();
}

function showLogin(message=''){
  const el=overlay(`<div class="cloud-auth"><div class="cloud-logo">TA</div><div class="eyebrow">Secure Team APP</div><h1>Sign in</h1><p>Adult coach and guardian accounts keep team data synchronized across devices.</p>${message?`<div class="cloud-error">${esc(message)}</div>`:''}<div class="cloud-tabs"><button data-auth-tab="signin" class="active">Sign in</button><button data-auth-tab="signup">Create account</button></div><form id="cloudAuthForm"><div class="field" data-name-field hidden><label>Name</label><input name="name" autocomplete="name"></div><div class="field"><label>Email</label><input name="email" type="email" autocomplete="username" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="10" autocomplete="current-password" required></div><label class="cloud-adult" data-adult-field hidden><input type="checkbox" name="adult"> I am an adult coach, staff member, or guardian.</label><button class="primary-btn cloud-wide" id="cloudAuthSubmit">Sign in</button></form><div class="cloud-auth-alt"><span class="cloud-small">Secure email/password sign-in is provided by Neon Managed Auth.</span></div><p class="cloud-small">Child athletes do not need accounts. Guardians manage youth profiles.</p></div>`);
  let mode='signin';el.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>{mode=b.dataset.authTab;el.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===b));el.querySelector('[data-name-field]').hidden=mode!=='signup';el.querySelector('[data-adult-field]').hidden=mode!=='signup';el.querySelector('#cloudAuthSubmit').textContent=mode==='signup'?'Create adult account':'Sign in';});
  el.querySelector('#cloudAuthForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),btn=el.querySelector('#cloudAuthSubmit');try{buttonBusy(btn,true);if(mode==='signup'){if(!f.get('adult'))throw new Error('Confirm that this is an adult account.');const result=await authClient.signUp.email({email:String(f.get('email')),password:String(f.get('password')),name:String(f.get('name')||f.get('email'))});if(result.error)throw new Error(result.error.message);}else{const result=await authClient.signIn.email({email:String(f.get('email')),password:String(f.get('password'))});if(result.error)throw new Error(result.error.message);}closeOverlay();await afterLogin();}catch(err){showLogin(err.message);}finally{buttonBusy(btn,false);}};
}

function showFirstTeam(){const el=overlay(`<div class="eyebrow">First team</div><h2>Create your coaching workspace</h2><p>You can add more teams and sports afterward.</p><form id="firstTeamForm"><div class="field"><label>Sport</label><select name="sportKey">${['baseball','softball','soccer','basketball','football','volleyball'].map(k=>`<option value="${k}">${k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select></div><div class="field"><label>Team name</label><input name="name" required placeholder="Red Lightning"></div><div class="field"><label>Season</label><input name="season" required value="${new Date().getFullYear()} Season"></div><button class="primary-btn cloud-wide">Create team</button></form>`);el.querySelector('#firstTeamForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),sportKey=String(f.get('sportKey')),name=String(f.get('name')),seasonName=String(f.get('season'));try{await api('/api/teams',{method:'POST',body:JSON.stringify({name,sportKey,season:seasonName,context:{}})});closeOverlay();await afterLogin();}catch(err){alert(err.message);}};}

function cloudTeamToLocal(d){return {id:`cloud-${d.id}`,remoteId:d.id,name:d.name,shortName:d.short_name||'',sportKey:d.sport_key,sport:d.sport_key?.[0]?.toUpperCase()+d.sport_key?.slice(1),season:d.season_name||'Season',ageGroup:d.age_group||'',division:d.division||'',leagueKey:d.league_key||'recreation',leagueName:d.league_name||'Local Recreation League',governingBody:d.governing_body||'',competitionProfileId:d.competition_profile_key||'',ruleSet:d.rule_label||d.division||'Custom / Recreation',ruleSourceUrl:d.rule_source_url||'',ruleSourceNote:d.rule_source_note||'',localRulesNote:d.local_rules_note||'',localRuleDetails:d.local_rule_details||{},homeLocation:d.home_location||{},branding:d.branding||{},staff:Array.isArray(d.staff)?d.staff:[],color:d.color||d.branding?.primaryColor||'#0f4c3a',defaultLayouts:d.default_layouts||{}};}

function scheduleSync(){if(hydrating||!runtime||!session)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncActive().catch(e=>console.warn('[cloud sync]',e)),900);}
async function syncActive(force=false){
  const p=activePayload();if(!p)return syncResult('noop');
  if(!navigator.onLine){const queued=await queuePayload(p);return syncResult(queued?'queued':'queue-failed');}
  let remoteId=p.teamRecord.remoteId;
  if(!remoteId){if(!force)return syncResult('noop');const created=await api('/api/teams',{method:'POST',body:JSON.stringify({name:p.teamRecord.name,shortName:p.teamRecord.shortName,sportKey:p.teamRecord.sportKey,season:p.teamRecord.season,teamRecord:p.teamRecord,context:p.context})});remoteId=created.team.id;const revision=Number(created.revision||1);revisions.set(remoteId,revision);runtime.assignRemoteId?.(p.teamRecord.id,remoteId);me=await api('/api/me');return syncResult('created',{remoteId,revision});}
  if(conflicts.has(remoteId)&&!force)return syncResult('conflict',{remoteId,conflict:conflicts.get(remoteId)});
  const revision=revisions.get(remoteId)??0;
  try{const result=await api(`/api/teams/${remoteId}/state`,{method:'PUT',body:JSON.stringify({revision,teamRecord:p.teamRecord,context:p.context})});const nextRevision=Number(result.revision);revisions.set(remoteId,nextRevision);await removeQueued(remoteId);return syncResult('synced',{remoteId,revision:nextRevision});}
  catch(e){
    if(e.status===409){const conflict=e.data||{};conflicts.set(remoteId,conflict);runtime.toast?.('Cloud conflict: this team changed on another device. Open Account to resolve.');return syncResult('conflict',{remoteId,conflict});}
    if(e.status===401){handleAuthLoss();return syncResult('auth-lost',{remoteId});}
    if(!e.status||e.status===429||e.status>=500){const queued=await queuePayload(p);if(queued)return syncResult('queued',{remoteId,error:e});return syncResult('queue-failed',{remoteId,error:e});}
    throw e;
  }
}
async function queuePayload(p){
  const remoteId=p?.teamRecord?.remoteId;if(!remoteId)return false;
  const queue=window.TEAM_APP_CLOUD_QUEUE,ownerUserId=me?.user?.id||session?.user?.id||null;
  if(!queue?.put){runtime?.toast?.('Offline cloud queue is unavailable. Your coaching changes remain local only on this device.');return false;}
  if(!ownerUserId){runtime?.toast?.('Sign in again before adding more changes to the cloud sync queue. Your current coaching changes remain local on this device.');return false;}
  const existingAny=(await allQueuedRows()).find(([id])=>id===remoteId)?.[1];
  if(existingAny?.ownerUserId&&existingAny.ownerUserId!==ownerUserId){runtime?.toast?.('Another adult account has unsynced changes for this team on this device. Sign back into that account to finish syncing before replacing them.');return false;}
  const existingBase=Number(existingAny?.baseRevision),currentBase=Number(revisions.get(remoteId));
  const baseRevision=Number.isFinite(existingBase)?existingBase:(Number.isFinite(currentBase)?currentBase:0);
  const ok=await queue.put(remoteId,{ownerUserId,baseRevision,teamRecord:p.teamRecord,context:p.context});
  if(ok===false)runtime?.toast?.('Your coaching changes remain saved locally, but this team could not be added to the cloud sync queue. Reconnect before clearing site data or changing devices.');
  return ok===true;
}
async function removeQueued(id){await window.TEAM_APP_CLOUD_QUEUE?.remove?.(id);}
async function flushQueue(){
  const outcomes=[];if(!navigator.onLine)return outcomes;
  const rows=await queuedRows(),ownerUserId=me?.user?.id||session?.user?.id||null;
  for(const [id,p] of rows){
    if(conflicts.has(id)){outcomes.push(syncResult('conflict',{remoteId:id,conflict:conflicts.get(id)}));continue;}
    if(!p?.ownerUserId){const conflict={revision:Number(revisions.get(id)||0),reason:'queued_owner_unknown'};conflicts.set(id,conflict);runtime?.toast?.('Saved offline changes were created by an older queue format and need review before cloud sync. Open Account to choose which copy to keep.');outcomes.push(syncResult('conflict',{remoteId:id,conflict}));continue;}
    if(p.ownerUserId!==ownerUserId)continue;
    const baseRevision=Number(p?.baseRevision);
    if(!Number.isFinite(baseRevision)){
      const conflict={revision:Number(revisions.get(id)||0),reason:'queued_revision_missing'};conflicts.set(id,conflict);runtime?.toast?.('Saved offline changes need review before cloud sync because they were created by an older queue format. Open Account to choose which copy to keep.');outcomes.push(syncResult('conflict',{remoteId:id,conflict}));continue;
    }
    try{const result=await api(`/api/teams/${id}/state`,{method:'PUT',body:JSON.stringify({revision:baseRevision,teamRecord:p.teamRecord,context:p.context})});const nextRevision=Number(result.revision);revisions.set(id,nextRevision);await removeQueued(id);outcomes.push(syncResult('synced',{remoteId:id,revision:nextRevision}));}
    catch(e){
      if(e.status===409){const conflict=e.data||{revision:Number(revisions.get(id)||baseRevision)};conflicts.set(id,conflict);runtime?.toast?.('Cloud conflict: saved offline changes were based on an older team version. Open Account to resolve.');outcomes.push(syncResult('conflict',{remoteId:id,conflict}));}
      else if(e.status===401){handleAuthLoss();outcomes.push(syncResult('auth-lost',{remoteId:id}));break;}
      else if(!e.status||e.status===429||e.status>=500)outcomes.push(syncResult('queued',{remoteId:id,error:e}));
      else{const conflict={revision:Number(revisions.get(id)||baseRevision),reason:'sync_rejected',message:e.message};conflicts.set(id,conflict);runtime?.toast?.('Saved offline changes could not be accepted by the cloud. Open Account to review before retrying.');outcomes.push(syncResult('conflict',{remoteId:id,conflict}));}
    }
  }
  return outcomes;
}
window.addEventListener('online',()=>flushQueue().then(()=>syncActive().catch(console.warn)).catch(console.warn));

