function bytesToBase64(bytes){let out='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk)out+=String.fromCharCode(...bytes.subarray(i,i+chunk));return btoa(out);}
function base64ToBytes(value){const raw=atob(value),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out;}
async function uploadDocument(file,meta){const rid=activeRemoteId();if(!rid)throw new Error('Publish the team to cloud first.');if(file.size>5*1024*1024)throw new Error('Cloud staging currently supports team documents up to 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer()),contentBase64=bytesToBase64(bytes);const r=await rpc('app_document_upload',{p_team:rid,p_name:file.name,p_content_type:file.type||'application/octet-stream',p_category:meta?.category||'General',p_visibility:meta?.visibility||'team',p_description:meta?.description||null,p_content_base64:contentBase64});return {id:r.documentId,name:file.name,type:file.type||'application/octet-stream',size:file.size,...meta,uploadedAt:new Date().toISOString(),cloud:true};}
