async function shareConversationKey(conv,key,keyVersion=1){const e2=window.TEAM_APP_E2EE;if(!e2||!key)return;const members=await api(`/api/conversations/${conv.id}/members`),keys=members.filter(m=>m.public_key_jwk);const envelopes=[];for(const m of keys)envelopes.push({recipientUserId:m.id,...await e2.wrapKeyFor(conv.id,keyVersion,key,m.public_key_jwk)});if(envelopes.length)await api(`/api/conversations/${conv.id}/key-envelopes`,{method:'PUT',body:JSON.stringify({keyVersion,envelopes})});}
